import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Pembagi gambar memotong satu gambar menjadi beberapa bagian yang lebih kecil. Bagian-bagian itu bisa membentuk grid untuk profil sosial, strip untuk carousel, atau irisan untuk mencetak gambar besar di banyak halaman. Gambar asli tetap utuh; pembagi hanya memberikan bagian-bagiannya.</p>\n<p><a href=\"/id/bagi-gambar/\">Pembagi gambar</a> membagi foto menjadi ubin grid N x M, baris horizontal, atau strip vertikal, dan mengunduh bagian-bagiannya satu per satu atau sekaligus sebagai ZIP. Alat ini berjalan sepenuhnya di browser Anda, jadi foto Anda tidak pernah meninggalkan perangkat.</p>\n<p>Panduan ini menjelaskan tiga mode pembagian, preset, pilihan ekspor, dan pekerjaan yang paling cocok untuk setiap mode. Baik Anda merencanakan grid Instagram, mengiris panorama, atau memotong tangkapan layar panjang untuk dicetak, pembagiannya adalah ide sederhana yang sama.</p>\n<h2 id=\"what-is-an-image-splitter\">Apa Itu Pembagi Gambar?</h2>\n<p>Pembagi gambar membagi satu gambar menjadi sekumpulan gambar yang lebih kecil di sepanjang garis potong lurus. Pembagian grid 3 x 3 mengubah satu foto persegi menjadi sembilan ubin persegi. Pembagian strip horizontal mengubah gambar tinggi menjadi baris-baris bertumpuk, dan pembagian strip vertikal mengubah gambar lebar menjadi kolom-kolom berdampingan.</p>\n<p>Setiap ubin adalah file gambar sungguhan, bukan pratinjau potongan. Anda bisa mengunduh ubin satu per satu atau sekaligus dalam ZIP, lalu memakainya di mana pun gambar terpisah dibutuhkan: unggahan sosial, halaman cetak, ubin permainan, atau mockup desain.</p>\n<p>Pembagian ini tidak merusak. File asli tidak pernah berubah, dan Anda bisa membagi gambar yang sama lagi dengan pengaturan berbeda sebanyak yang Anda mau. Grid 3 x 3 hari ini dan grid 2 x 4 besok sama-sama berasal dari sumber yang tidak tersentuh.</p>\n<p>Membagi berbeda dengan memotong. Memotong membuang sebagian gambar untuk mempertahankan satu bagian, sedangkan membagi mempertahankan setiap bagian dan memberikan semuanya. Ubin-ubin itu bersama-sama berisi seluruh gambar asli, hanya dalam file terpisah.</p>\n<h2 id=\"grid-mode\">Mode Grid: Ubin N x M</h2>\n<p>Mode grid adalah mode utama. Anda mengatur jumlah baris dan kolom, dan alat membagi gambar menjadi ubin yang sama banyak. Grid 3 x 3 menghasilkan sembilan ubin, grid 2 x 4 menghasilkan delapan, dan grid maksimum adalah 10 x 10, yang menghasilkan seratus ubin dari satu gambar.</p>\n<p>Grid adalah mode untuk grid profil Instagram, di mana sembilan ubin persegi membentuk satu gambar besar di seluruh halaman profil. Mode ini juga untuk puzzle, mosaik, dan tata letak apa pun yang ubinnya duduk berdampingan untuk membangun kembali gambar asli.</p>\n<p>Setiap ubin dipotong pada dimensi piksel asli yang penuh, jadi foto 3000 piksel yang dibagi 3 x 3 menghasilkan sembilan ubin 1000 piksel. Tidak ada yang diperkecil atau di-resample, yang berarti ubin tetap cukup tajam untuk dicetak atau diunggah dengan kualitas penuh.</p>\n<p>Garis potong bernomor muncul di pratinjau, jadi Anda bisa melihat persis di mana setiap ubin dimulai dan berakhir sebelum mengunduh. Jika garis potong melewati wajah atau detail penting, ubah grid atau reposisikan gambar, daripada menerima potongan yang buruk.</p>\n<h2 id=\"horizontal-strips\">Strip Horizontal</h2>\n<p>Strip horizontal memotong gambar menjadi baris-baris bertumpuk. Gambar tinggi yang dibagi menjadi empat strip horizontal menghasilkan empat gambar lebar dan pendek yang dibaca dari atas ke bawah, seperti halaman-halaman dokumen panjang.</p>\n<p>Mode ini cocok untuk tangkapan layar panjang yang perlu dicetak. Tangkapan layar satu halaman penuh terlalu tinggi untuk satu lembar kertas, tetapi empat strip horizontal tercetak bersih di empat halaman. Ide yang sama bekerja untuk infografis tinggi yang perlu dibagikan sebagai slide terpisah.</p>\n<p>Strip horizontal juga cocok untuk carousel sosial, di mana setiap slide melanjutkan gambar ke bawah. Penonton menggeser strip demi strip dan gambar terungkap dengan sendirinya secara berurutan, sehingga tercipta efek bercerita yang sederhana.</p>\n<p>Pilih jumlah strip sesuai tujuan. Empat strip untuk empat halaman cetak, tiga untuk carousel tiga slide, dan dua untuk pembagian atas-bawah yang sederhana. Strip-strip itu sama tinggi, jadi konten terbagi merata.</p>\n<h2 id=\"vertical-strips\">Strip Vertikal</h2>\n<p>Strip vertikal memotong gambar menjadi kolom-kolom berdampingan. Panorama lebar yang dibagi menjadi tiga strip vertikal menghasilkan tiga gambar tinggi yang dibaca dari kiri ke kanan, seperti panel triptych.</p>\n<p>Mode ini cocok untuk panorama lebar dan banner yang terlalu lebar untuk satu unggahan atau satu halaman. Panorama yang dibagi menjadi strip vertikal bisa diunggah sebagai carousel, di mana setiap geseran mengungkap bagian berikutnya dari pemandangan, dan ini cocok untuk fotografi perjalanan dan lanskap.</p>\n<p>Strip vertikal juga cocok untuk banner dan header situs web yang perlu dibangun kembali di beberapa kolom. Desainer bisa menempatkan setiap strip di kolomnya sendiri dan merakit kembali panorama dalam tata letak yang tidak bisa memuat satu gambar lebar.</p>\n<p>Seperti strip horizontal, strip-strip ini sama lebar, jadi konten terbagi merata. Panorama dengan subjek di tengah mungkin butuh jumlah strip ganjil, agar subjek mendarat di strip tengah, bukan pada garis potong.</p>\n<h2 id=\"split-presets\">Preset Pembagian</h2>\n<p>Preset adalah pengaturan pembagian sekali klik untuk pekerjaan yang umum. Grid Instagram 3 x 3 adalah preset yang paling dikenal, tetapi alat ini menyertakan preset lain untuk ukuran grid dan jumlah strip yang umum, jadi Anda bisa melewatkan pengaturan baris dan kolom secara manual.</p>\n<p>Preset adalah titik awal, bukan aturan. Ketuk preset 3 x 3 untuk grid Instagram, lalu sesuaikan baris atau kolom jika gambar atau rencana Anda butuh bentuk berbeda. Preset mengisi angka-angkanya, dan Anda tetap bebas mengubahnya.</p>\n<p>Preset membantu saat Anda sering membagi gambar. Manajer media sosial yang membuat grid setiap minggu bisa mengetuk preset yang sama setiap kali dan mendapat ukuran ubin yang sama, sehingga grid profil tetap konsisten dari satu puzzle ke puzzle berikutnya.</p>\n<p>Jika tidak ada preset yang cocok dengan pekerjaan Anda, atur baris dan kolom dengan tangan. Grid 4 x 5 untuk poster, strip 1 x 6 untuk banner, atau grid 5 x 5 untuk mosaik semuanya pembagian yang valid, dan kontrol manual mencakup setiap kombinasi sampai 10 x 10.</p>\n<h2 id=\"full-resolution-tiles\">Ubin Resolusi Penuh</h2>\n<p>Ubin dipotong pada dimensi piksel asli yang penuh, yang berarti pembagian tidak pernah menurunkan kualitas. Foto 3000 x 3000 piksel yang dibagi menjadi sembilan ubin menghasilkan sembilan gambar 1000 x 1000 piksel, masing-masing setajam bagian yang sesuai dari gambar asli.</p>\n<p>Ini penting untuk pencetakan dan layar besar. Ubin yang diperkecil akan tampak lembut saat dicetak atau dilihat pada ukuran penuh, sedangkan ubin resolusi penuh mempertahankan detail yang sama dengan sumbernya. Pembagi adalah alat pemotong, bukan alat pengubah ukuran.</p>\n<p>Sebagai gantinya, ada ukuran file. Sembilan ubin resolusi penuh bersama-sama kira-kira sama besarnya dengan gambar asli, dan pembagian 10 x 10 menghasilkan seratus file untuk dikelola. Unduh ZIP agar file-file itu tetap bersama, daripada menyimpan setiap ubin dengan tangan.</p>\n<p>Periksa ukuran file ubin Anda sebelum mengunggah ke media sosial. Ubin resolusi penuh dari foto besar bisa berukuran beberapa megabyte, dan beberapa platform memperkecilnya secara otomatis. Kompres ubin jika perlu, tetapi jangan pernah memulai dari sumber kecil.</p>\n<p>Simpan sumber asli Anda bersama ubin yang sudah dibagi. Jika platform mengubah ukuran grid atau Anda ingin membagi lagi dengan jumlah berbeda, sumber asli memungkinkan Anda memulai dari awal tanpa kehilangan kualitas.</p>\n<p>Beri nama folder ubin dengan jelas, misalnya grid-instagram-liburan-2026. Nama yang jelas mencegah kebingungan saat Anda punya beberapa pembagian dalam satu folder unduhan.</p>\n<p>Mulailah dari sumber beresolusi tertinggi yang Anda punya. Foto 600 piksel yang dibagi 3 x 3 menghasilkan sembilan ubin 200 piksel, yang tampak baik sebagai thumbnail tetapi buruk sebagai unggahan. Sumber besar menghasilkan ubin besar, dan ubin besar bertahan di setiap penggunaan.</p>\n<h2 id=\"numbered-tiles-and-zip-download\">Ubin Bernomor dan Unduhan ZIP</h2>\n<p>Setiap ubin diberi nomor agar Anda tahu di mana letaknya. Penomoran mengikuti urutan baca: kiri ke kanan, atas ke bawah, dimulai dari sudut kiri atas. Ubin satu adalah bagian kiri atas, dan ubin terakhir adalah bagian kanan bawah.</p>\n<p>Penomoran paling penting untuk grid Instagram, di mana ubin harus diunggah dalam urutan terbalik agar mendarat di tempat yang benar. Nomor-nomor itu memberi tahu posisi grid setiap ubin, jadi urutan unggah tidak pernah ditebak.</p>\n<p>Unduhan ZIP berisi semua ubin dalam satu file, diberi nama secara berurutan. Mengunduh ZIP lebih cepat daripada menyimpan setiap ubin satu per satu, dan membuat set itu tetap bersama di perangkat Anda. Ekstrak, dan file-file bernomor siap dipakai.</p>\n<p>Anda juga bisa mengunduh ubin satu per satu jika hanya butuh satu atau dua. Satu ubin untuk foto profil atau satu strip untuk banner tidak membutuhkan seluruh set, dan unduhan individual menghemat repot mengekstrak.</p>\n<h2 id=\"input-formats\">Format Masukan</h2>\n<p>Pembagi menerima file JPG, PNG, WebP, HEIC, GIF, BMP, dan SVG hingga 20 MB. Foto dari ponsel, tangkapan layar, dan grafis dari alat desain semuanya bekerja tanpa konversi. Foto HEIC dari iPhone diunggah dan dibagi seperti file lainnya.</p>\n<p>Format ubin mengikuti pilihan Anda, bukan masukan. Sumber JPG bisa menghasilkan ubin PNG, dan sumber PNG bisa menghasilkan ubin JPG. Pilih format sesuai tujuan: JPG untuk foto dan file kecil, PNG untuk transparansi dan grafis tajam.</p>\n<p>Perhatikan bahwa slider Kualitas Ubin hanya muncul untuk ubin JPG. Ubin PNG bersifat lossless, jadi tidak ada pengaturan kualitas yang perlu disesuaikan. Jika Anda butuh file terkecil, pilih JPG dan atur kualitasnya; jika Anda butuh piksel yang persis, pilih PNG.</p>\n<p>GIF animasi tidak dibagi sebagai animasi. Mengunggah GIF animasi memberi Anda ubin dari satu frame, bukan sekumpulan ubin animasi. Bagi gambar diam untuk grid dan strip, dan biarkan animasi tetap utuh.</p>\n<h2 id=\"transparency-and-sprite-sheets\">Transparansi dan Sprite Sheet</h2>\n<p>Membagi PNG transparan mempertahankan transparansi di setiap ubin. Sprite sheet dengan sel transparan dibagi menjadi ubin transparan, dan itulah yang dibutuhkan pengembang game saat memotong lembar ikon atau tileset menjadi sprite individual.</p>\n<p>Pilih PNG sebagai format ubin untuk pekerjaan transparan. JPG tidak punya transparansi, jadi ubin transparan yang diekspor sebagai JPG mendapat latar solid, biasanya putih atau hitam. Transparansi hanya bertahan saat format mendukungnya.</p>\n<p>Sprite sheet butuh potongan yang persis. Lembar ikon 32 x 32 piksel yang dibagi menjadi grid menghasilkan ubin tepat 32 piksel masing-masing, selama dimensi lembar terbagi rata. Periksa dimensi ubin setelah pembagian sebelum memakainya di game engine.</p>\n<p>Saat lembar tidak terbagi rata, ubin tepi mungkin sedikit berbeda ukurannya. Itu normal untuk pembagian grid, dan artinya lembar punya margin atau celah yang tidak diperhitungkan grid. Pangkas dulu sumbernya ke kelipatan yang persis untuk ubin yang sempurna secara piksel.</p>\n<h2 id=\"splitting-for-print\">Membagi untuk Cetak</h2>\n<p>Gambar besar yang dicetak di beberapa halaman adalah kegunaan cetak klasik untuk pembagi. Poster yang dibagi menjadi grid ubin tercetak di banyak lembar kertas, yang Anda pangkas dan sambung menjadi poster besar. Nomor ubin memberi tahu urutannya.</p>\n<p>Strip horizontal cocok untuk dokumen panjang dan banner yang perlu dicetak di beberapa halaman. Infografis tinggi yang dibagi menjadi empat strip tercetak di empat halaman, masing-masing satu bagian bersih dari gambar asli. Strip-strip itu sama tinggi, jadi halaman-halamannya cocok.</p>\n<p>Periksa dimensi ubin terhadap ukuran kertas sebelum mencetak. Ubin yang lebih lebar daripada area cetak akan terpotong oleh printer, sedangkan ubin yang jauh lebih kecil membuang kertas. Atur grid agar setiap ubin cocok dengan satu lembar.</p>\n<p>Cetak pada resolusi penuh dan jangan biarkan printer menskalakan ubin. Ubin yang diskalakan kehilangan ketajaman yang dipertahankan pembagian resolusi penuh. Atur printer ke ukuran sebenarnya, dan ubin akan tersambung dengan bersih.</p>\n<h2 id=\"splitting-screenshots\">Membagi Tangkapan Layar</h2>\n<p>Tangkapan layar panjang adalah hal yang paling sering dibagi orang. Tangkapan layar satu halaman penuh dari situs web atau chat terlalu tinggi untuk dibaca dengan nyaman dan terlalu tinggi untuk dicetak, tetapi strip horizontal mengubahnya menjadi bagian-bagian yang bisa dibaca.</p>\n<p>Tempel tangkapan layar langsung dari clipboard dengan Ctrl dan V. Pembagi menerima gambar yang ditempel, jadi tangkapan layar tidak pernah perlu disimpan sebagai file dulu. Tempel, pilih jumlah strip, dan unduh bagian-bagiannya.</p>\n<p>Pilih jumlah strip sesuai konten. Tangkapan layar dengan empat bagian alami dibagi menjadi empat strip, sedangkan halaman yang sangat panjang mungkin butuh enam atau delapan. Lebih banyak strip berarti bagian yang lebih pendek dan lebih mudah dibaca, tetapi juga lebih banyak file untuk dikelola.</p>\n<p>Waspadai garis potong yang melewati teks. Batas strip yang melewati baris teks membuat kedua strip sulit dibaca. Sesuaikan jumlah strip sampai batasnya jatuh di celah antara paragraf atau bagian.</p>\n<h2 id=\"common-mistakes\">Kesalahan yang Umum</h2>\n<p>Kesalahan paling umum adalah membagi gambar beresolusi rendah menjadi terlalu banyak ubin. Foto 600 piksel yang dibagi 3 x 3 menghasilkan sembilan ubin 200 piksel, yang tampak buruk sebagai unggahan. Mulailah dari sumber besar, atau pakai ubin yang lebih sedikit.</p>\n<p>Kesalahan lain adalah garis potong yang melewati wajah atau detail kunci. Pratinjau menunjukkan garis potong sebelum Anda mengunduh, jadi periksa dan sesuaikan grid atau posisi gambar. Wajah yang terbagi di dua ubin tampak seperti kesalahan, bukan desain.</p>\n<p>Kesalahan ketiga adalah memilih format ubin yang salah. Ubin transparan yang diekspor sebagai JPG kehilangan transparansinya dan mendapat latar solid. Pilih PNG kapan pun transparansi penting, dan JPG saat ukuran file penting.</p>\n<p>Terakhir, banyak orang lupa urutan unggah untuk grid. Instagram menampilkan unggahan terbaru lebih dulu, jadi ubin grid harus diunggah dalam urutan terbalik agar mendarat dengan benar. Nomor ubin memberi posisi grid; unggah dari ubin terakhir ke yang pertama.</p>\n<h2 id=\"quick-reference\">Referensi Cepat: Checklist Pembagian</h2>\n<p>Mulailah dari sumber besar, pilih mode Grid, Horizontal, atau Vertikal, dan atur baris dan kolom atau ketuk preset. Periksa garis potong bernomor di pratinjau, terutama di sekitar wajah dan teks.</p>\n<p>Pilih JPG untuk foto dan PNG untuk transparansi, unduh ZIP, dan unggah ubin grid dalam urutan terbalik. Jika potongan mendarat dengan buruk, ubah grid dan bagi lagi, daripada menerimanya.</p>\n<p>Untuk versi langkah demi langkah, baca <a href=\"/id/blog/cara-membagi-gambar/\">Cara Membagi Gambar</a>, dan untuk grid Instagram secara detail, baca <a href=\"/id/blog/cara-membagi-gambar-untuk-grid-instagram/\">Membagi Gambar untuk Grid dan Puzzle Instagram</a>. Bagi gambar Anda dengan <a href=\"/id/bagi-gambar/\">pembagi gambar</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Apa bedanya membagi dan memotong gambar?","answer":"Memotong mempertahankan satu bagian gambar dan membuang sisanya. Membagi mempertahankan setiap bagian dan memberikannya semua sebagai file terpisah. Ubin-ubin itu bersama-sama berisi seluruh gambar asli, hanya dibagi di sepanjang garis potong lurus."},{"question":"Apakah membagi akan menurunkan kualitas foto saya?","answer":"Tidak. Ubin dipotong pada dimensi piksel asli yang penuh, jadi setiap ubin setajam bagian yang sesuai dari sumbernya. Kualitas hanya turun jika Anda mulai dari sumber beresolusi rendah, karena ubinnya juga kecil."},{"question":"Berapa grid terbesar yang bisa saya pakai untuk membagi gambar?","answer":"Grid maksimum adalah 10 x 10, yang menghasilkan 100 ubin dari satu gambar. Kebanyakan pekerjaan butuh jauh lebih sedikit: 3 x 3 untuk grid Instagram, 2 x 2 untuk pembagian sederhana, atau beberapa strip untuk tangkapan layar panjang."},{"question":"Bisakah saya membagi gambar menjadi bagian yang tidak sama besar?","answer":"Tidak, pembagi membagi gambar menjadi ubin atau strip yang sama besar. Jika dimensi gambar tidak terbagi rata, ubin tepi mungkin berbeda satu atau dua piksel. Untuk bagian yang tidak sama persis, potong setiap bagian secara terpisah dengan pemotong gambar."},{"question":"Apakah ubin yang dibagi mempertahankan format file asli?","answer":"Anda memilih sendiri format ubinnya. Sumber JPG bisa menghasilkan ubin PNG, dan sumber PNG bisa menghasilkan ubin JPG. Pilih JPG untuk foto dan file kecil, dan PNG saat Anda butuh transparansi atau piksel yang persis."},{"question":"Mengapa saya membagi gambar, bukan sekadar mengunggah seluruh foto?","answer":"Pembagian melayani pekerjaan yang tidak bisa dilakukan satu gambar: puzzle grid di seluruh halaman profil, carousel yang mengungkap panorama geseran demi geseran, poster yang dicetak di banyak halaman, atau tangkapan layar panjang yang dibagi menjadi bagian yang bisa dibaca."}];
